<template><PageHeader :title="ticket?.title || 'Ticket not found'" subtitle="Ticket details and troubleshooting information."><RouterLink class="btn" to="/tickets">← Back to tickets</RouterLink></PageHeader><div v-if="ticket" class="grid-2"><section class="panel"><div class="detail-top"><span class="badge open">{{ticket.status}}</span><span class="priority high">{{ticket.priority}} priority</span></div><h2>{{ticket.id}}</h2><p class="detail-description">{{ticket.description}}</p><div class="detail-grid"><div><small>Requester</small><strong>{{ticket.requester}}</strong></div><div><small>Room</small><strong>{{ticket.room}}</strong></div><div><small>Category</small><strong>{{ticket.category}}</strong></div><div><small>Last updated</small><strong>{{ticket.updated}}</strong></div></div></section><section class="panel"><h2>Activity</h2><div class="timeline"><div><b>Ticket created</b><small>System · Today</small></div><div><b>Assigned to IT Support</b><small>System · Today</small></div><div><b>Investigation pending</b><small>Waiting for technician update</small></div></div><button class="btn primary full">Mark as resolved</button></section></div></template>
<script setup>import { computed } from 'vue'; import { useRoute } from 'vue-router'; import PageHeader from '../components/PageHeader.vue'; import { tickets } from '../data/data.js'; const route=useRoute(); const ticket=computed(()=>tickets.find(t=>t.id===route.params.id))</script>
